CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_diag_subtypes_sin_concepto` AS
select `m`.`subtype` AS `subtype`,count(0) AS `metricas`,count(distinct `m`.`id_dev`) AS `dispositivos`,min(left(coalesce(nullif(`m`.`c_label`,''),`m`.`label`),60)) AS `ejemplo_label`,(case when (`m`.`subtype` like 'xagt\\_%') then 'xagt(estandar)' when (`m`.`subtype` like 'custom\\_%') then 'custom(local)' when (`m`.`subtype` like 'w\\_mon\\_%') then 'w_mon' else 'otro' end) AS `familia` from `metrics` `m` where ((coalesce(`m`.`status`,0) in (0,2)) and (not(`m`.`subtype` in (select `sem_metric_concept`.`subtype` from `sem_metric_concept`)))) group by `m`.`subtype`;
